let AC, bgm=true, mt=null, step=0, sunoOn=false;
const BGM_TRACKS = {
  town: { m: [0,4,7,12,11,7,4,7,5,9,12,9,7,4,2,4], b: [0,0,5,7], s: 230, type:'square' },
  route: { m: [9,12,16,12,14,11,7,11,9,12,14,16,17,16,14,11], b: [9,5,7,4], s: 190, type:'square' },
  beach: { m: [12,14,16,19,16,14,12,7,9,12,14,12,9,7,5,7], b: [0,-5,-2,-7], s: 260, type:'sine' },
  knowledge: { m: [7,11,14,18,14,11,7,2,5,9,12,9,5,2,0,4], b: [7,2,0,-3], s: 280, type:'triangle' },
  sports: { m: [0,7,4,7,2,7,5,7,0,7,4,9,7,5,4,2], b: [0,-3,-5,-7], s: 160, type:'square' },
  indoor: { m: [4,7,11,7,4,2,0,2,4,7,9,7,4,2,0,-3], b: [0,0,-5,-5], s: 300, type:'sine' }
};

function tone(n,d,ty,v,t0){
  if(!AC||AC.state!='running')return;   // 멈춘 동안 음이 쌓였다가 한꺼번에 터지지 않게 함
  const o=AC.createOscillator(),gn=AC.createGain(),t=AC.currentTime+(t0||0);
  o.type=ty;o.frequency.value=261.63*2**(n/12);
  gn.gain.setValueAtTime(v,t);
  gn.gain.exponentialRampToValueAtTime(.0001,t+d);
  o.connect(gn);gn.connect(AC.destination);
  o.start(t);o.stop(t+d);
}

function music(){
  clearInterval(mt);npUpdate();
  if(!AC||!bgm||!map||sunoOn)return;
  const trackKey = map.bgm || (map.o ? (cur=='route1'?'route':'town') : 'indoor');
  const T = BGM_TRACKS[trackKey] || BGM_TRACKS.town;
  step = 0;
  mt = setInterval(()=>{
    tone(T.m[step%16], .22, T.type, .035);
    if(step%4===0) tone(T.b[(step/4|0)%4]-12, .8, 'triangle', .06);
    step++;
  }, T.s);
}

function sfx(k){
  if(!bgm)return;
  if(k=='b')tone(-12,.08,'square',.04);
  else if(k=='t')tone(14+Math.random()*3,.03,'square',.015);
  else if(k=='w'){[0,4,7,12].forEach((n,i)=>tone(n,.12,'square',.04,i*.07))}
  else tone(12,.06,'square',.04);
}

/* 모바일 브라우저·인앱 브라우저는 소리가 멈춘 채 시작될 수 있어서, 터치할 때마다 깨움 */
function acUnlock(){
  try{
    if(!AC)AC=new(window.AudioContext||window.webkitAudioContext)();
    if(AC.state!='running'){const p=AC.resume();if(p&&p.catch)p.catch(()=>{});
      const b=AC.createBuffer(1,1,22050),s=AC.createBufferSource();s.buffer=b;s.connect(AC.destination);s.start(0)}
  }catch(e){}
}
['pointerup','touchend','click','keydown'].forEach(t=>addEventListener(t,()=>{if(AC&&AC.state!='running')acUnlock()},{capture:true,passive:true}));
function togBgm(){bgm=!bgm;$('#bg').textContent=bgm?'🔊':'🔇';if(TRAIN_S.kind){bgm?rideStart():rideStop();npUpdate();return}bgm&&!sunoOn?music():clearInterval(mt);npUpdate()}
/* 위쪽 재생 이름 */
let npExt='',npLast=null;
const BGM_NAMES={town:'BS World Main Theme',route:'Olle Walk',beach:'Jeju Coast',knowledge:'Academy City',sports:'Fitness Center',indoor:'Cozy Room'};
function npUpdate(){const el=document.getElementById('npt');if(!el)return;
  const key=map?(map.bgm||'town'):'town',tx=sunoOn&&npExt?'♪ '+npExt:bgm?'♪ '+BGM_NAMES[key]:'🔇 음악 꺼짐';
  if(tx!==npLast){npLast=tx;el.textContent=tx}}
/* 탭을 떠나 있는 동안에만 게임 음악을 쉼 (소리 설정은 그대로) */
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearInterval(mt);else{if(AC&&AC.state!='running')acUnlock();if(!sunoOn)music()}});

